# Reference only — not wired into the running app. Lumen is the wisdom/inference tekton in
# chorus, and its UI surface belongs to facet — a crystal's face. This file is kept for
# integration into facet's own routes/pages; see README.md in this folder.
#
# This is the chat UI shell plus the two non-generation BFF surfaces (/api/login proxying
# Origin, /api/history reading Mantle chat-message artifacts) plus the 501-refusing
# /api/chat[/stream] stubs, verbatim. It references `host`/`app` objects from the retired
# service and will not run standalone.
# ---------------------------------------------------------------------------
# Chat UI — a minimal BFF so the browser talks only to this host (no cross-
# subdomain CORS). Lumen forwards login → Origin and history → Mantle server-side,
# following agience standards: every chat turn is stored as a Mantle **artifact**
# (content_type ``application/vnd.agience.chat-message+json``), grouped by session.
# ---------------------------------------------------------------------------
ORIGIN_INTERNAL = os.getenv("ORIGIN_INTERNAL", "http://127.0.0.1:8080")
MANTLE_INTERNAL = os.getenv("MANTLE_INTERNAL", "http://127.0.0.1:8082")
CHAT_CT = "application/vnd.agience.chat-message+json"


def _bearer(authorization):
    """Normalize an Authorization header to ``Bearer <jwt>`` (browser sends the raw JWT)."""
    if not authorization:
        return None
    a = authorization.strip()
    return a if a.lower().startswith("bearer ") else f"Bearer {a}"


@app.post("/api/login")
def api_login(body: dict):
    """Proxy password login to Origin (the IDP). Returns the operator JWT + name."""
    import httpx

    try:
        r = httpx.post(f"{ORIGIN_INTERNAL}/auth/password/login", json={
            "identifier": body.get("identifier", ""), "password": body.get("password", "")},
            timeout=20)
    except Exception as e:  # pragma: no cover
        return {"ok": False, "error": str(e)[:120]}
    if r.status_code != 200:
        return {"ok": False, "error": "invalid credentials"}
    tok = r.json().get("access_token", "")
    name = ""
    try:
        import base64
        import json as _j
        pad = tok.split(".")[1]
        pad += "=" * (-len(pad) % 4)
        name = _j.loads(base64.urlsafe_b64decode(pad)).get("name", "")
    except Exception:
        pass
    return {"ok": True, "token": tok, "name": name}


# No writer exists on this host: both generation routes refuse before they would write
# anything, so nothing here posts a chat turn to Mantle. A refusal is a status code, never
# a stored turn.
#
# `CHAT_CT` is retained: `/api/history` still reads artifacts of that content type, so turns
# already stored are unaffected by the refusal above.


# `/api/chat`, `/api/chat/stream` and `/api/history` carry `host.auth_dependency` explicitly,
# because they are mounted straight onto `app` rather than through the `@host.operator` decorator
# that attaches auth as a per-route dependency for every operator route. `_bearer` only shapes a
# header; it never checks a signature, issuer, or audience, so the routes need their own gate.
# `auth_dependency` is the same check the operator routes use, so the Origin operator token that
# `/api/login` already hands the browser (RS256, `aud=agience` in the `lumen,agience` default)
# still verifies — and when no auth is configured the verifier is disabled and dev is unaffected.
@app.post("/api/chat", dependencies=[Depends(host.auth_dependency)])
def api_chat(body: dict, authorization: str | None = Header(default=None)):
    """Always returns 501 — Lumen connects to no model, so there is no grounding pass, model
    alias, or generation call. Nothing is persisted: the refusal precedes any store write, so
    a refused request never leaves a stored user turn without a matching assistant reply.

    `/api/history`, `/api/login`, and the UI shell are unaffected — only the generation leg
    is absent. `host.auth_dependency` still authenticates the caller before refusing, so the
    route cannot be used as an unauthenticated probe for whether Lumen is up.
    """
    _no_generation_tier()


# There is no local token-streaming decoder here.


@app.post("/api/chat/stream", dependencies=[Depends(host.auth_dependency)])
def api_chat_stream(body: dict):
    """Always returns 501 — Lumen connects to no model.

    No `StreamingResponse` is ever returned, so headers are never sent and the 501 survives on
    the status line rather than opening as a 200 SSE stream.

    `authorization`/`token` are not in the signature because this route never reads the corpus
    or the store. `host.auth_dependency` still gates the route.

    The UI's submit handler distinguishes 401/403 from every other failure and renders the
    server's `detail` rather than treating any non-OK response as a session expiry — see
    `_CHAT_HTML`, `SESSION-EXPIRED`.
    """
    _no_generation_tier()


@app.get("/api/history", dependencies=[Depends(host.auth_dependency)])
def api_history(session: str = "", authorization: str | None = Header(default=None)):
    """Return this operator's chat-message artifacts (optionally one session)."""
    import httpx

    token = _bearer(authorization)
    if not token:
        return {"ok": False, "error": "not authenticated"}
    try:
        r = httpx.get(f"{MANTLE_INTERNAL}/artifacts/visible", headers={"authorization": token}, timeout=20)
        arts = r.json() if r.status_code == 200 else []
    except Exception:
        arts = []
    msgs = [{"role": a.get("name", "user"), "text": a.get("content", ""),
             "session": a.get("context", ""), "time": a.get("created_time", "")}
            for a in arts if a.get("content_type") == CHAT_CT and (not session or a.get("context") == session)]
    msgs.sort(key=lambda m: m["time"])
    return {"ok": True, "messages": msgs}


AGIENCE_LOGO = "data:image/png;base64,"   # the real Agience wordmark (from Facet), embedded


@app.get("/", response_class=HTMLResponse)
def chat_ui():
    # The visible UI is branded "Lumen" only — the underlying model is an implementation detail
    # (still reported by the API's /v1/models and in provenance, just not shown to the user).
    return _CHAT_HTML.replace("__LOGO__", AGIENCE_LOGO)


_CHAT_HTML = r"""<!doctype html><html><head><meta charset=utf-8>
<meta name=viewport content="width=device-width,initial-scale=1">
<title>Agience · Lumen</title>
<link href="https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,100..1000&display=swap" rel=stylesheet>
<link rel=stylesheet href="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css">
<script src="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js"></script>
<style>
*{box-sizing:border-box}
:root{--ink:#1f2937;--muted:#6b7280;--faint:#9ca3af;--line:#e5e7eb;--indigo:#6366f1;--indigo-d:#4f46e5;--ink9:#111827}
body{margin:0;font-family:'DM Sans',-apple-system,Segoe UI,Roboto,sans-serif;color:var(--ink);
  min-height:100vh;background:#0b0e18;overflow-x:hidden}
/* facet animated background: rotating conic gradient + blurred blobs */
#bg{position:fixed;inset:0;z-index:-2;background:#111827;overflow:hidden}
#bg .g{position:absolute;left:50%;top:50%;width:200vmax;height:200vmax;border-radius:50%;
  background:conic-gradient(from 0deg,#581c87,#1e3a8a,#581c87);transform:translate(-50%,-50%);
  animation:rot 32s linear infinite}
#bg .b{position:absolute;border-radius:50%;filter:blur(6vmin);opacity:.55}
#bg .b1{width:52vmin;height:52vmin;background:#581c87;left:8%;top:12%;animation:f1 34s ease-in-out infinite}
#bg .b2{width:44vmin;height:44vmin;background:#6d28d9;right:6%;bottom:8%;animation:f2 40s ease-in-out infinite}
#bg .b3{width:36vmin;height:36vmin;background:#1e3a8a;left:40%;top:60%;animation:f1 46s ease-in-out infinite}
@keyframes rot{to{transform:translate(-50%,-50%) rotate(360deg)}}
@keyframes f1{0%,100%{transform:translate(0,0)}50%{transform:translate(18vmin,-12vmin)}}
@keyframes f2{0%,100%{transform:translate(0,0)}50%{transform:translate(-16vmin,10vmin)}}
.wrap{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px}
/* frosted-glass card */
.card{width:100%;background:rgba(255,255,255,.94);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
  border:1px solid rgba(255,255,255,.6);border-radius:20px;box-shadow:0 24px 60px -20px rgba(0,0,0,.55);}
#loginCard{max-width:400px;padding:34px 30px}
#appCard{max-width:860px;height:min(86vh,760px);display:flex;flex-direction:column;overflow:hidden}
.logo{text-align:center;margin-bottom:22px}
.logo img{height:38px;width:auto;max-width:70%}
.chdr img.brand{height:22px;width:auto;display:block}
h1{text-align:center;font-size:18px;font-weight:500;color:#374151;margin:0 0 22px}
input,textarea{width:100%;padding:11px 13px;border:1px solid #d1d5db;border-radius:10px;font-size:14px;font-family:inherit;color:var(--ink);background:#fff}
textarea{resize:none;overflow-y:auto;max-height:170px;line-height:1.5}
input:focus{outline:none;border-color:transparent;box-shadow:0 0 0 2px #818cf8}
label{display:block;font-size:13px;font-weight:500;color:#374151;margin:14px 0 6px}
button{cursor:pointer;border:0;border-radius:10px;font-weight:600;font-family:inherit}
.primary{width:100%;padding:11px;background:var(--ink9);color:#fff;font-size:14px;margin-top:18px;transition:background .15s}
.primary:hover{background:#1f2937}.primary:disabled{opacity:.5;cursor:default}
.link{background:none;color:var(--indigo);font-size:12px;padding:6px 0}.link:hover{text-decoration:underline}
#err{color:#dc2626;background:#fef2f2;border:1px solid #fecaca;border-radius:10px;padding:0;margin-top:12px;font-size:13px;min-height:0;overflow:hidden;transition:all .2s}
#err.show{padding:9px 12px;min-height:18px}
.foot{text-align:center;font-size:12px;color:var(--faint);margin-top:22px}.foot a{color:var(--indigo);text-decoration:none}
/* chat */
.chdr{display:flex;align-items:center;gap:12px;padding:16px 22px;border-bottom:1px solid var(--line)}
.chdr b{font-weight:700;color:var(--ink9)}.chdr b span{color:var(--indigo-d)}
.chdr .sub{color:var(--faint);font-size:12px}.chdr .sp{margin-left:auto}
#logout{background:#f3f4f6;color:#6b7280;padding:7px 12px;font-size:12px}
#chat{flex:1;overflow-y:auto;padding:22px;display:flex;flex-direction:column;gap:14px}
.msg{padding:11px 15px;border-radius:14px;max-width:80%;white-space:pre-wrap;word-wrap:break-word;font-size:14.5px;line-height:1.55}
.user{align-self:flex-end;background:var(--ink9);color:#fff;border-bottom-right-radius:5px}
.assistant{align-self:flex-start;background:#f3f4f6;color:var(--ink);border-bottom-left-radius:5px}
.assistant.streaming::after{content:'▍';color:var(--indigo);animation:blink 1s steps(2) infinite}
@keyframes blink{50%{opacity:0}}
.trunc{align-self:flex-start;font-size:11px;color:#b91c1c;margin:-8px 0 2px 6px}
/* a server refusal (e.g. the 501 from /api/chat/stream) rendered in the reply slot — styled to
   read plainly as an ERROR, never as an assistant turn. See SESSION-EXPIRED below. */
.err{color:#b91c1c;background:#fef2f2;border:1px solid #fecaca;font-size:13px;line-height:1.45}
.dim{color:var(--faint);font-size:13px;text-align:center;align-self:center}
form#f{display:flex;gap:10px;padding:16px 22px;border-top:1px solid var(--line);align-items:flex-end}
#q{flex:1}#send{background:var(--ink9);color:#fff;padding:0 22px;height:44px;flex:none}
/* rendered markdown inside an assistant bubble */
.msg.md{white-space:normal}
.msg.md>*:first-child{margin-top:0}.msg.md>*:last-child{margin-bottom:0}
.msg.md p{margin:.5em 0}
.msg.md h1,.msg.md h2,.msg.md h3{margin:.7em 0 .3em;line-height:1.25;font-weight:700}
.msg.md h1{font-size:1.3em}.msg.md h2{font-size:1.18em}.msg.md h3{font-size:1.05em}
.msg.md ul,.msg.md ol{margin:.4em 0;padding-left:1.4em}
.msg.md li{margin:.15em 0}
.msg.md code{background:rgba(99,102,241,.12);padding:.12em .38em;border-radius:5px;font-size:.9em;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.msg.md pre{background:#1e2230;color:#e6e9f2;padding:11px 13px;border-radius:9px;overflow-x:auto;margin:.55em 0}
.msg.md pre code{background:none;padding:0;color:inherit;font-size:.86em;line-height:1.5}
.msg.md a{color:var(--indigo-d);text-decoration:underline}
.msg.md blockquote{margin:.5em 0;padding:.2em 0 .2em .9em;border-left:3px solid var(--indigo);color:var(--faint)}
.msg.md strong{font-weight:700}.msg.md hr{border:none;border-top:1px solid var(--line);margin:.8em 0}
.msg.md .katex-display{overflow-x:auto;overflow-y:hidden;margin:.55em 0;padding:2px 0}
.msg.md .katex{font-size:1.02em}
.msg.md .math-src{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.92em;opacity:.85}
.hide{display:none!important}
</style></head><body>
<div id=bg><div class=g></div><div class="b b1"></div><div class="b b2"></div><div class="b b3"></div></div>

<div class=wrap>
  <!-- SP has no login page — we deep-link straight to the Origin IdP. -->
  <div id=loginCard class=card style="text-align:center">
    <div class=logo><img src="__LOGO__" alt="Agience"></div>
    <div class=foot style="margin-top:14px">Redirecting to sign in…</div>
  </div>

  <!-- APP -->
  <div id=appCard class="card hide">
    <div class=chdr>
      <img class=brand src="__LOGO__" alt="Agience"> <span class=sub>Lumen</span>
      <span class=sp></span><button id=logout>Sign out</button>
    </div>
    <div id=chat></div>
    <form id=f><textarea id=q rows=1 placeholder="Message Lumen…  (Shift+Enter for a new line)" autocomplete=off></textarea><button id=send class=primary style="margin-top:0;width:auto">Send</button></form>
  </div>
</div>

<script>
const S=sessionStorage,chat=document.getElementById('chat'),f=document.getElementById('f'),q=document.getElementById('q'),
  send=document.getElementById('send'),loginCard=document.getElementById('loginCard'),appCard=document.getElementById('appCard'),
  err=document.getElementById('err');
const ORIGIN_LOGIN='https://origin.agience.ai/login';
function tok(){return S.getItem('lumen_token')}
function sess(){let s=S.getItem('lumen_session');if(!s){s='sess-'+Math.random().toString(36).slice(2)+Date.now().toString(36);S.setItem('lumen_session',s)}return s}
// --- minimal, XSS-safe markdown -> HTML (escape first, then structure). Math-aware. ---
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function inline(s){ // s is already HTML-escaped; @@..@@ sentinels never occur in real prose
  const codes=[];
  s=s.replace(/`([^`]+)`/g,(m,c)=>{codes.push('<code>'+c+'</code>');return '@@CODE'+(codes.length-1)+'@@'});
  s=s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
  s=s.replace(/(^|[^*\w])\*([^*]+)\*/g,'$1<em>$2</em>');
  s=s.replace(/(^|[^_\w])_([^_]+)_/g,'$1<em>$2</em>');
  s=s.replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
  s=s.replace(/@@CODE(\d+)@@/g,(m,i)=>codes[+i]);
  return s;
}
function mathHTML(tex,display,render){
  if(render&&window.katex){try{return katex.renderToString(tex,{displayMode:display,throwOnError:false})}catch(e){}}
  const d=display?'$$':'$';return '<span class="math-src">'+d+esc(tex)+d+'</span>';   // streaming / no-katex: show source
}
function md(src,opts){
  const render=!(opts&&opts.math===false);           // math typeset only when asked (off mid-stream to avoid flicker)
  src=(src||'').replace(/\r\n/g,'\n');
  const fences=[],maths=[];
  src=src.replace(/```(\w*)\n?([\s\S]*?)```/g,(m,l,c)=>{fences.push('<pre><code>'+esc(c.replace(/\n+$/,''))+'</code></pre>');return '@@FENCE'+(fences.length-1)+'@@'});
  src=src.replace(/\$\$([\s\S]+?)\$\$/g,(m,t)=>{maths.push([t,true]);return '@@MATH'+(maths.length-1)+'@@'});
  src=src.replace(/\\\[([\s\S]+?)\\\]/g,(m,t)=>{maths.push([t,true]);return '@@MATH'+(maths.length-1)+'@@'});
  src=src.replace(/\$(?!\s)([^\n$]+?)(?<!\s)\$/g,(m,t)=>{maths.push([t,false]);return '@@MATH'+(maths.length-1)+'@@'});
  src=src.replace(/\\\(([\s\S]+?)\\\)/g,(m,t)=>{maths.push([t,false]);return '@@MATH'+(maths.length-1)+'@@'});
  const lines=src.split('\n'),out=[];let i=0,buf=[];
  const para=()=>{if(buf.length){out.push('<p>'+inline(esc(buf.join(' ')))+'</p>');buf=[]}};
  while(i<lines.length){const ln=lines[i];
    if(/^@@FENCE\d+@@$/.test(ln.trim())){para();out.push(ln.trim());i++;continue}
    if(/^#{1,3}\s/.test(ln)){para();const lvl=ln.match(/^#+/)[0].length;out.push('<h'+lvl+'>'+inline(esc(ln.replace(/^#+\s/,'')))+'</h'+lvl+'>');i++;continue}
    if(/^\s*[-*]\s+/.test(ln)){para();const it=[];while(i<lines.length&&/^\s*[-*]\s+/.test(lines[i])){it.push('<li>'+inline(esc(lines[i].replace(/^\s*[-*]\s+/,'')))+'</li>');i++}out.push('<ul>'+it.join('')+'</ul>');continue}
    if(/^\s*\d+\.\s+/.test(ln)){para();const it=[];while(i<lines.length&&/^\s*\d+\.\s+/.test(lines[i])){it.push('<li>'+inline(esc(lines[i].replace(/^\s*\d+\.\s+/,'')))+'</li>');i++}out.push('<ol>'+it.join('')+'</ol>');continue}
    if(/^\s*>\s?/.test(ln)){para();const bq=[];while(i<lines.length&&/^\s*>\s?/.test(lines[i])){bq.push(inline(esc(lines[i].replace(/^\s*>\s?/,''))));i++}out.push('<blockquote>'+bq.join('<br>')+'</blockquote>');continue}
    if(/^\s*(---|\*\*\*|___)\s*$/.test(ln)){para();out.push('<hr>');i++;continue}
    if(ln.trim()===''){para();i++;continue}
    buf.push(ln);i++;
  }
  para();
  let html=out.join('');
  html=html.replace(/@@MATH(\d+)@@/g,(m,n)=>mathHTML(maths[+n][0],maths[+n][1],render));
  html=html.replace(/@@FENCE(\d+)@@/g,(m,n)=>fences[+n]);
  return html;
}
function add(role,text){const d=document.createElement('div');d.className='msg '+role;
  if(role==='assistant'&&text){d.classList.add('md');d.innerHTML=md(text,{math:true})}else{d.textContent=text}
  chat.appendChild(d);chat.scrollTop=chat.scrollHeight;return d}
function show(a){loginCard.classList.toggle('hide',a);appCard.classList.toggle('hide',!a)}
function seterr(m){err.textContent=m||'';err.classList.toggle('show',!!m)}

// SP has no login page — deep-link straight to the Origin IdP (Origin=IdP, Lumen=SP).
function gotoLogin(){
  location.replace(ORIGIN_LOGIN+'?redirect_uri='+encodeURIComponent(location.origin+'/')
    +'&state=st-'+Math.random().toString(36).slice(2));
}
document.getElementById('logout').onclick=()=>{S.clear();chat.innerHTML='';convo.length=0;show(false)};

async function loadHistory(){
  chat.innerHTML='<div class=dim>loading…</div>';
  const r=await fetch('/api/history?session='+encodeURIComponent(sess()),{headers:{'Authorization':tok()}});
  const o=await r.json();chat.innerHTML='';convo.length=0;
  if(o.ok&&o.messages.length){o.messages.forEach(m=>{add(m.role,m.text);convo.push({role:m.role,content:m.text})})}
  else add('assistant','Hi'+(S.getItem('lumen_name')?' '+S.getItem('lumen_name'):'')+" — I’m Lumen. Ask me anything; this conversation is saved as artifacts in Mantle.");
}

const convo=[];
// textarea: Enter sends, Shift+Enter inserts a newline; grow with content up to the CSS max.
function grow(){q.style.height='auto';q.style.height=Math.min(q.scrollHeight,170)+'px'}
q.addEventListener('input',grow);
q.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();
  if(typeof f.requestSubmit==='function')f.requestSubmit();else f.dispatchEvent(new Event('submit',{cancelable:true}))}});
f.onsubmit=async e=>{
  e.preventDefault();const text=q.value.trim();if(!text)return;
  q.value='';grow();send.disabled=true;add('user',text);convo.push({role:'user',content:text});
  const cur=add('assistant','');cur.classList.add('streaming');let acc='';
  let r;try{r=await fetch('/api/chat/stream',{method:'POST',headers:{'Content-Type':'application/json','Authorization':tok()},
    body:JSON.stringify({session:sess(),messages:convo})})}catch(_){cur.textContent='[network error]';cur.classList.remove('streaming');send.disabled=false;return}
  // SESSION-EXPIRED: only 401/403 mean the session is actually gone. Every OTHER non-2xx —
  // notably the 501 that /api/chat/stream now always returns, since Lumen connects to no model
  // [John, 2026-07-20] — used to be reported as '[session expired]', which cleared the token and
  // bounced the operator to login. That is a false diagnosis of a deliberate refusal, and it
  // destroyed the session as a side effect. Show the server's own `detail` instead, and stay
  // logged in: history and login still work, only generation is gone.
  if(!r.ok){
    if(r.status===401||r.status===403){cur.textContent='[session expired]';cur.classList.remove('streaming');S.clear();send.disabled=false;gotoLogin();return}
    let d='';try{d=(await r.json()).detail||''}catch(_){}
    cur.textContent='['+r.status+'] '+(d||'this request could not be served');
    cur.classList.add('err');cur.classList.remove('streaming');send.disabled=false;q.focus();return}
  const rd=r.body.getReader(),dec=new TextDecoder();let buf='';
  while(true){const {value,done}=await rd.read();if(done)break;buf+=dec.decode(value,{stream:true});
    let i;while((i=buf.indexOf('\n\n'))>=0){const line=buf.slice(0,i);buf=buf.slice(i+2);
      if(!line.startsWith('data: '))continue;const o=JSON.parse(line.slice(6));
      if(o.t!==undefined){acc+=o.t;cur.classList.add('md');cur.innerHTML=md(acc,{math:false});chat.scrollTop=chat.scrollHeight}
      if(o.done){convo.push({role:'assistant',content:acc});
        cur.classList.add('md');cur.innerHTML=md(acc,{math:true});chat.scrollTop=chat.scrollHeight;   // formatted as produced; math typeset on completion
        if(o.truncated){const b=document.createElement('div');b.className='trunc';
          b.textContent='response hit the length limit';cur.after(b);chat.scrollTop=chat.scrollHeight;}}
    }}
  cur.classList.remove('streaming');send.disabled=false;q.focus();
};

// SSO return: Origin sends the token back in the URL fragment.
(function(){const h=new URLSearchParams(location.hash.slice(1));const t=h.get('access_token');
  if(t){S.setItem('lumen_token',t);history.replaceState(null,'',location.pathname);}})();
if(tok()){show(true);loadHistory()}else{show(false);gotoLogin();}
</script></body></html>"""


def main() -> None:
    """Console entrypoint (``agience-lumen`` / ``python -m lumen``)."""
    host.serve(port=int(os.getenv("PORT", "8084")))
